UPDATE "ExerciseRecord"
SET "data" = '{"id":"farbenpass-kompass","title":"Farbenpass-Kompass","description":"Der Trainer ruft eine Farbe. Nur die Kinder am passenden Farbtor passen durch ihr Tor und tauschen anschließend die Plätze.","duration":12,"players":"8–16","ageGroup":"F-Jugend","ageRange":"U8/U9","category":"Einstieg","accent":"#58a6ff","intensity":"Mittel","focus":["Passspiel","Reaktion","Orientierung"],"setup":"Vier verschiedenfarbige Hütchentore mit viel Abstand als Kompass aufbauen. An jedem Tor stehen sich zwei kleine Gruppen gegenüber; die erste Gruppe hat einen Ball. Der Trainer ruft eine Farbe. Am gerufenen Tor passt das erste Kind flach durch das Tor, läuft dem Ball nach und stellt sich gegenüber an. Der Empfänger nimmt den Ball an und wartet auf das nächste Farbkommando.","coaching":["Zuerst Farbe hören, dann starten","Ball flach und mittig durch das Tor spielen","Dem Pass sofort auf die andere Seite folgen","Empfänger steht bereit und nimmt mit dem ersten Kontakt sauber an","Zunächst nur eine Farbe rufen; später zwei Farben gleichzeitig"],"materials":[{"id":"balls","count":4},{"id":"cones","count":8},{"id":"bibs","count":4}],"fieldSize":"20 × 20 m","variant":20}'::jsonb,
